  s:[{f:"1000-01-01",t:"1081-12-01",d:"bizans",kesinlik:"yil",kaynak:"TDV seyzer «II. Basileios tarafından ikinci defa ele geçirilmesinden itibaren (389/999) seksen yıl kadar Bizans idaresinde kaldı» | TDV seyzer «Bizans’a tâbi Bâre piskoposunun elindeki Şeyzer’i alıp burada Münkızoğulları Emirliği’ni kurdu (Receb 474 / Aralık 1081)» | hicrî 389 ∩ 999 = 999-01-01; bitiş Receb 474/Aralık 1081 (ay hassasiyeti). 1024 Mirdâsî iktâsı (Mukalled'e) Şeyzer'i değil Kefertâb'ı etkiledi (TDV: \"Sadece Kefertâb'da hâkimiyet kurabilen Mukalled\"). | f 1000-01-01 UFUK SINIR İŞARETİDİR (sahiplik öncesinden sürüyor) · VERI-MS1-1281"},
    {f:"1081-12-01",t:"1086-04-18",d:"__BOSLUK__",kesinlik:"ay",kaynak:"BOŞLUK BEYANI (arandı, bulunamadı): sahip Şeyzer Münkızoğulları (munkizogullari künyesi 1081-01-01.. var, BOYALAR'da YOK -> yeni_kunye_gerekli boya). || TDV seyzer «Bizans’a tâbi Bâre piskoposunun elindeki Şeyzer’i alıp burada Münkızoğulları Emirliği’ni kurdu (Receb 474 / Aralık 1081)» · VERI-MS1-1281"},
    {f:"1086-04-18",t:"1128-01-06",d:"buyuk-selcuklu",kesinlik:"yil",kaynak:"TDV seyzer «Melikşah’a bağlılık arzetmesiyle Şeyzer ve çevresi Selçuklu hâkimiyeti altına girdi (479/1086)» | BEYANLI: Münkızoğulları emirleri yerinde kaldı (vasal); hicrî 479 ∩ 1086 ilk günü. · VERI-MS1-1281"},
    {f:"1128-01-06",t:"1157-08-01",d:"zengi-musul",kesinlik:"yil",kaynak:"TDV seyzer «Sultan b. Ali’nin Musul Atabegi İmâdüddin Zengî’nin himayesini kabul etmesinin (522/1128)» | BEYANLI YAKLAŞIKLIK: himaye (vasallık), doğrudan idare değil; bitiş Receb 552 (Ağustos 1157) depremi sonrası Nûreddin'in yönetimi devralması (ay hassasiyeti). · VERI-MS1-1281"},
    {f:"1157-08-01",t:"1183-06-12",d:"zengi-halep",kesinlik:"ay",kaynak:"TDV seyzer «Receb 552’de (Ağustos 1157) meydana gelen depremde büyük yıkıma uğradı» | TDV seyzer «Nûreddin Mahmud Zengî, Haçlılar’a karşı yürüttüğü mücadelede stratejik önem taşıyan şehri tamir ve tahkim ettirip yönetimini sütkardeşi Mecdüddin b. Dâye’ye verdi» | bitiş zengi-halep künye sonu (Selâhaddîn'in Halep'i alışı); Mecdüddin b. Dâye ailesi 1236'ya dek yönetti. · VERI-MS1-1281"},
    {f:"1183-06-12",t:"1186-01-01",d:"eyyubi",kesinlik:"yil",kaynak:"TDV seyzer «Selâhaddîn-i Eyyûbî döneminde Eyyûbî hâkimiyetine giren şehrin» | BEYANLI: Eyyûbî hâkimiyetine giriş yılı TDV'de yok; 1183-06-12 Halep'in Selâhaddîn'e geçişi, bitiş eyyubi-halep künye başı. · VERI-MS1-1281"},
    {f:"1186-01-01",t:"1260-09-03",d:"eyyubi-halep",kesinlik:"yil",kaynak:"TDV seyzer «Halep Eyyûbî melikliğine bağlanan Şeyzer 638 (1241) yılında Hârizmliler’in saldırılarını bertaraf etmeye muvaffak oldu» | TDV seyzer «yönetimi 634 (1236) yılına kadar bu ailenin elinde kaldı» | bitiş eyyubi-halep künye sonu (Ayn Câlût). · VERI-MS1-1281"},
    {f:"1260-09-03",t:"1262-01-01",d:"__BOSLUK__",kesinlik:"yil",kaynak:"BOŞLUK BEYANI (arandı, bulunamadı): tahrip ≠ sahiplik; 1260-1262 sahibi kaynakta yok. || TDV seyzer «Suriye’nin 1260’ta mâruz kaldığı Moğol istilâsı sırasında Şeyzer’in de tahrip edildiğini düşündürmektedir» · VERI-MS1-1281"},
    {f:"1262-01-01",t:"1516-01-01",d:"memluk",kesinlik:"yil",kaynak:"TDV seyzer «Memlük Sultanı I. Baybars’ın 660’ta (1262) bölgede yaptığı teftiş sırasında onarılmasını emrettiği merkezler içinde bulunması» | TDV seyzer «Şeyzer, Memlük idarî teşkilâtında Halep nâibliğine bağlandı» | bitiş: Yavuz Sultan Selim'in Suriye fethi 1516 (yıl hassasiyeti). · VERI-MS1-1281"}],
  d:[{f:"1516-01-01",t:"1850-01-01",kaynak:"TDV seyzer «Yavuz Sultan Selim’in Suriye’yi fethi üzerine Osmanlı topraklarına katılan bölgenin idarî yapısı yeniden tanzim edildi» | TDV seyzer «XIX. yüzyılın ortalarına kadar meskûn olan şehrin» | BEYAN: yıl hassasiyeti; bitiş = terk (XIX. yy ortası, yüzyıl-ortası alt/üst sınır). · VERI-MS1-1281"}],
